20	import * as zrUtil from 'zrender/src/core/util';
21	import ChartView from '../../view/Chart';
22	import * as graphic from '../../util/graphic';
23	import { setStatesStylesFromModel, toggleHoverEmphasis } from '../../util/states';
24	import Path, { PathProps } from 'zrender/src/graphic/Path';
25	import {createClipPath} from '../helper/createClipPathFromCoordSys';
26	import CandlestickSeriesModel, { CandlestickDataItemOption } from './CandlestickSeries';
27	import GlobalModel from '../../model/Global';
28	import ExtensionAPI from '../../core/ExtensionAPI';
29	import { StageHandlerProgressParams } from '../../util/types';
30	import SeriesData from '../../data/SeriesData';
31	import {CandlestickItemLayout} from './candlestickLayout';
32	import { CoordinateSystemClipArea } from '../../coord/CoordinateSystem';
33	import Model from '../../model/Model';
34	import { saveOldStyle } from '../../animation/basicTransition';
35	import Element from 'zrender/src/Element';
36	import { getBorderColor, getColor } from './candlestickVisual';
37	
38	const SKIP_PROPS = ['color', 'borderColor'] as const;
39	
40	class CandlestickView extends ChartView {
41	
42	    static readonly type = 'candlestick';
43	    readonly type = CandlestickView.type;
44	
45	    private _isLargeDraw: boolean;
46	
47	    private _data: SeriesData;
48	
49	    private _progressiveEls: Element[];
50	
51	    render(seriesModel: CandlestickSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
52	        // If there is clipPath created in large mode. Remove it.
53	        this.group.removeClipPath();
54	        // Clear previously rendered progressive elements.
55	        this._progressiveEls = null;
56	
57	        this._updateDrawMode(seriesModel);
58	
59	        this._isLargeDraw
60	            ? this._renderLarge(seriesModel)
61	            : this._renderNormal(seriesModel);
62	    }
63	
64	    incrementalPrepareRender(seriesModel: CandlestickSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
65	        this._clear();
66	        this._updateDrawMode(seriesModel);
67	    }
68	
69	    incrementalRender(
70	        params: StageHandlerProgressParams,
71	        seriesModel: CandlestickSeriesModel,
72	        ecModel: GlobalModel,
73	        api: ExtensionAPI
74	    ) {
75	        this._progressiveEls = [];
76	        this._isLargeDraw
77	             ? this._incrementalRenderLarge(params, seriesModel)
78	             : this._incrementalRenderNormal(params, seriesModel);
79	    }
80	
81	    eachRendered(cb: (el: Element) => boolean | void) {
82	        graphic.traverseElements(this._progressiveEls || this.group, cb);
83	    }
84	
85	    _updateDrawMode(seriesModel: CandlestickSeriesModel) {
86	        const isLargeDraw = seriesModel.pipelineContext.large;
87	        if (this._isLargeDraw == null || isLargeDraw !== this._isLargeDraw) {
88	            this._isLargeDraw = isLargeDraw;
89	            this._clear();
90	        }
91	    }
92	
93	    _renderNormal(seriesModel: CandlestickSeriesModel) {
94	        const data = seriesModel.getData();
95	        const oldData = this._data;
96	        const group = this.group;
97	        const isSimpleBox = data.getLayout('isSimpleBox');
98	
99	        const needsClip = seriesModel.get('clip', true);
100	        const coord = seriesModel.coordinateSystem;
101	        const clipArea = coord.getArea && coord.getArea();
102	
103	        // There is no old data only when first rendering or switching from
104	        // stream mode to normal mode, where previous elements should be removed.
105	        if (!this._data) {
106	            group.removeAll();
107	        }
108	
109	        data.diff(oldData)
110	            .add(function (newIdx) {
111	                if (data.hasValue(newIdx)) {
112	                    const itemLayout = data.getItemLayout(newIdx) as CandlestickItemLayout;
113	
114	                    if (needsClip && isNormalBoxClipped(clipArea, itemLayout)) {
115	                        return;
116	                    }
117	
118	                    const el = createNormalBox(itemLayout, newIdx, true);
119	                    graphic.initProps(el, {shape: {points: itemLayout.ends}}, seriesModel, newIdx);
120	
121	                    setBoxCommon(el, data, newIdx, isSimpleBox);
122	
123	                    group.add(el);
124	
125	                    data.setItemGraphicEl(newIdx, el);
126	                }
127	            })
128	            .update(function (newIdx, oldIdx) {
129	                let el = oldData.getItemGraphicEl(oldIdx) as NormalBoxPath;
130	
131	                // Empty data
132	                if (!data.hasValue(newIdx)) {
133	                    group.remove(el);
134	                    return;
135	                }
136	
137	                const itemLayout = data.getItemLayout(newIdx) as CandlestickItemLayout;
138	                if (needsClip && isNormalBoxClipped(clipArea, itemLayout)) {
139	                    group.remove(el);
140	                    return;
141	                }
142	
143	                if (!el) {
144	                    el = createNormalBox(itemLayout, newIdx);
145	                }
146	                else {
147	                    graphic.updateProps(el, {
148	                        shape: {
149	                            points: itemLayout.ends
150	                        }
151	                    }, seriesModel, newIdx);
152	
153	                    saveOldStyle(el);
154	                }
155	
156	                setBoxCommon(el, data, newIdx, isSimpleBox);
157	
158	                group.add(el);
159	                data.setItemGraphicEl(newIdx, el);
160	            })
161	            .remove(function (oldIdx) {
162	                const el = oldData.getItemGraphicEl(oldIdx);
163	                el && group.remove(el);
164	            })
165	            .execute();
166	
167	        this._data = data;
168	    }
169	
170	    _renderLarge(seriesModel: CandlestickSeriesModel) {
171	        this._clear();
172	
173	        createLarge(seriesModel, this.group);
174	
175	        const clipPath = seriesModel.get('clip', true)
176	            ? createClipPath(seriesModel.coordinateSystem, false, seriesModel)
177	            : null;
178	        if (clipPath) {
179	            this.group.setClipPath(clipPath);
180	        }
181	        else {
182	            this.group.removeClipPath();
183	        }
184	
185	    }
186	
187	    _incrementalRenderNormal(params: StageHandlerProgressParams, seriesModel: CandlestickSeriesModel) {
188	        const data = seriesModel.getData();
189	        const isSimpleBox = data.getLayout('isSimpleBox');
190	
191	        let dataIndex;
192	        while ((dataIndex = params.next()) != null) {
193	            const itemLayout = data.getItemLayout(dataIndex) as CandlestickItemLayout;
194	            const el = createNormalBox(itemLayout, dataIndex);
195	            setBoxCommon(el, data, dataIndex, isSimpleBox);
196	
197	            el.incremental = true;
198	            this.group.add(el);
199	
200	            this._progressiveEls.push(el);
201	        }
202	    }
